@using System.Timers
@implements IDisposable

<div class="notification-badge" @onclick="HandleClick">
    @if (_unreadCount > 0)
    {
        <span class="badge">@_unreadCount</span>
    }
</div>

@code {
    [Inject] private INotificationService NotificationService { get; set; } = default!;

    [Parameter] public EventCallback OnClick { get; set; }

    private int _unreadCount;
    private Timer? _pollingTimer;

    protected override async Task OnInitializedAsync()
    {
        _unreadCount = await NotificationService.GetUnreadCountAsync();

        NotificationService.OnNotificationReceived += HandleNotificationReceived;

        _pollingTimer = new Timer(30_000);
        _pollingTimer.Elapsed += PollUnreadCount;
        _pollingTimer.AutoReset = true;
        _pollingTimer.Start();
    }

    private void HandleNotificationReceived(Notification notification)
    {
        _unreadCount++;
        InvokeAsync(StateHasChanged);
    }

    private async void PollUnreadCount(object? sender, ElapsedEventArgs e)
    {
        try
        {
            var count = await NotificationService.GetUnreadCountAsync();
            if (count != _unreadCount)
            {
                _unreadCount = count;
                await InvokeAsync(StateHasChanged);
            }
        }
        catch
        {
            // Swallow polling errors to avoid crashing the component
        }
    }

    private async Task HandleClick()
    {
        await OnClick.InvokeAsync();
    }

    public void Dispose()
    {
        NotificationService.OnNotificationReceived -= HandleNotificationReceived;

        if (_pollingTimer is not null)
        {
            _pollingTimer.Elapsed -= PollUnreadCount;
            _pollingTimer.Stop();
            _pollingTimer.Dispose();
            _pollingTimer = null;
        }
    }
}

